local M = {}

local SKIN_DATA = ""

local INNER_DATA = ""

local CARVED_DATA = ""

local HOLLOW_DATA = ""

local function decode(data)
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local lookup = {}
	for i = 1, 64 do
		lookup[alphabet:byte(i)] = i - 1
	end
	local out, n, bits = {}, 0, 0
	for i = 1, #data do
		local v = lookup[data:byte(i)]
		if v then
			n = n * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local d = 2 ^ bits
				out[#out + 1] = string.char(math.floor(n / d))
				n = n % d
			end
		end
		if i % 30000 == 0 then
			task.wait()
		end
	end
	return table.concat(out)
end

local function buildMesh(data)
	local bytes = decode(data)
	local pos = 1
	local function u16()
		local lo, hi = bytes:byte(pos, pos + 1)
		pos = pos + 2
		return lo + hi * 256
	end
	local function s16()
		local v = u16()
		if v >= 32768 then
			v = v - 65536
		end
		return v
	end
	local function s8()
		local v = bytes:byte(pos)
		pos = pos + 1
		if v >= 128 then
			v = v - 256
		end
		return v
	end
	local vertCount = u16()
	local triCount = u16()
	local verts = {}
	for i = 1, vertCount do
		local x, y, z = s16() / 10000, s16() / 10000, s16() / 10000
		local nx, ny, nz = s8() / 127, s8() / 127, s8() / 127
		local u, v = u16() / 65535, u16() / 65535
		verts[i] = string.format("[%.6f,%.6f,%.6f][%.6f,%.6f,%.6f][%.6f,%.6f,0]", x, y, z, nx, ny, nz, u, v)
		if i % 800 == 0 then
			task.wait()
		end
	end
	local tris = {}
	for i = 1, triCount do
		tris[i] = verts[u16() + 1] .. verts[u16() + 1] .. verts[u16() + 1]
		if i % 800 == 0 then
			task.wait()
		end
	end
	return "version 1.01\n" .. triCount .. "\n" .. table.concat(tris)
end

function M.install()
	local asset = getcustomasset or getsynasset
	if type(writefile) ~= "function" or type(asset) ~= "function" then
		return nil
	end
	local urls = {}
	writefile("kryon_pumpkin_skin.jpg", decode(SKIN_DATA))
	urls.skin = asset("kryon_pumpkin_skin.jpg")
	writefile("kryon_pumpkin_inner.jpg", decode(INNER_DATA))
	urls.inner = asset("kryon_pumpkin_inner.jpg")
	writefile("kryon_pumpkin_carved.mesh", buildMesh(CARVED_DATA))
	urls.carved = asset("kryon_pumpkin_carved.mesh")
	writefile("kryon_pumpkin_hollow.mesh", buildMesh(HOLLOW_DATA))
	urls.hollow = asset("kryon_pumpkin_hollow.mesh")
	return urls
end

return M
